def sample_and_write_to_txt(data, n=50, output_file="sampled_data.txt"):
    """
    从原始数据中随机采样n行，并以相同格式写入txt文件
    
    Args:
        data: 原始数据列表（字符串格式）
        n: 要采样的行数
        output_file: 输出文件名
    """
    # 确保采样数量不超过数据总量
    n = min(n, len(data))
    
    # 随机采样
    sampled_data = random.sample(data, n)
    
    # 写入文件，保持原始格式
    with open(output_file, 'w', encoding='utf-8') as f:
        f.write('sample_data_raw = [\n')
        
        # 写入每一行数据
        for i, item in enumerate(sampled_data):
            # 处理每一行字符串数据，用单引号包裹
            # 注意：原始数据中可能包含单引号，需要进行转义处理
            formatted_item = item.replace("'", "\\'")  # 转义单引号
            
            # 写入格式化的数据行
            line_str = f"        '{formatted_item}'"
            
            # 如果不是最后一行，添加逗号
            if i < len(sampled_data) - 1:
                line_str += ','
            
            f.write(line_str + '\n')
        
        f.write(']')
    
    print(f"成功采样 {n} 行数据并保存到 {output_file}")
    print(f"原始数据行数: {len(data)}")
    print(f"采样数据行数: {len(sampled_data)}")
    
    # 返回采样的数据
    return sampled_data

def extract_application_ids(sampled_data):
    """
    从采样的数据中提取所有application_id
    
    Args:
        sampled_data: 采样后的数据列表
        
    Returns:
        list: application_id列表
    """
    application_ids = []
    
    for data_str in sampled_data:
        # 查找application_id字段
        if 'application_id:' in data_str:
            # 提取application_id值
            start_idx = data_str.find('application_id:') + len('application_id:')
            end_idx = data_str.find(',', start_idx)
            
            if end_idx == -1:  # 如果这是最后一个字段
                end_idx = len(data_str)
            
            app_id = data_str[start_idx:end_idx].strip()
            application_ids.append(app_id)
    
    return application_ids

